(window.webpackJsonp=window.webpackJsonp||[]).push([[30],{469:function(t,s,v){"use strict";v.r(s);var _=v(11),e=Object(_.a)({},(function(){var t=this,s=t.$createElement,v=t._self._c||s;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("p",[v("font",{attrs:{size:"5"}},[t._v("1、三个难题")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("启示录6：9~10节：揭开第五印的时候，我看见在祭坛底下有为神的道并作见证被杀之人的灵魂，大声喊着说：“圣洁真实的主啊！你不审判住在地上的人给我们申流血的冤，要等到几时呢？” 曾有一位朋友引用这处经文问我：“你们基督徒不是常讲‘饶恕’吗？这些人岂不是也没有饶恕？”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("还有一次，一位弟兄问我：“我有个不信主的朋友得罪了我，我该饶恕他吗？”我说：“该。”他接着问：“如果他一辈子都没信主，主会饶恕他吗？”我答：“不会。”他于是追问：“如果连主都不饶恕他，我却饶恕，难道我比主更宽容吗？”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("2022年，徐州“铁链女”事件被曝光，举国震动。一位朋友这样问：“我知道基督徒会怜悯那位受虐的女子，但对那个施暴的男人，你们怎么看？你们会选择饶恕他吗？如果饶恕，难道不觉得荒谬吗？你们毕竟不是受害者，有什么资格饶恕？”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("2、三个错误")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“饶恕”是基督信仰的核心。创造天地的神，在慈爱中差遣他的爱子耶稣基督道成肉身、降世为人。他在世上活了无罪的一生，最终却为全人类的罪死在十字架上，被神所咒诅，第三天复活，好叫一切世人通过信他，就能被神所饶恕、赦免。正因为此，耶稣在世时反复教导他的门徒要效法创造主，要“饶恕人”、“免人的债”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而在信仰实践中，“饶恕”对很多基督徒而言，却是难上加难。于是，一些人将世俗心理学的方法引入教会当中，试图通过某些轻松的、温吞的、舒适的方法，来抚平心灵的“创伤”。不可否认，这些方法确实能在某种程度上，让人在“心理上”表现出“放下”、“不纠结”、“不痛苦”的状态，似乎结出了“饶恕”的果实。但恕我直言，这种心理上的“疗愈”并无神奇之处。现代的世俗心理学可以做到，其实，自古以来人所创造的各种宗教法门也能做到。一位佛门修士，参悟到诸行无常、从而放下我执；又或一位道家行者，修行入物我两忘，从而逍遥自在，难道不也就可以在“心理上”饶恕那伤害他的人吗？但饶恕的心理状态，不等于饶恕的灵性果实。唯有按照创造主启示的真理、借着圣灵的光照、引导和扶持来认识自己、找出伤痛的根源，才能在病灶处入手，达到表里兼治、善树佳果的成效。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在信仰实践中，也有一些基督徒，在“饶恕”的操练上走入了另一条歪路。他们表现出一种看破红尘，心如止水，“躲进小楼成一统，管他冬夏与春秋”的淡定。他们以为基督徒灵性成熟到一定程度，则不再有情绪的波动，时时刻刻都处于“平安喜乐”当中。一些狂妄又愚昧的敌基督者把创造主的真理污蔑成是“鸦片”，而这些基督徒的此种状态，恰恰为他们的污蔑提供了注脚。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("还有另一些基督徒明白真理，知道当神的公义被践踏、真理被扭曲，我们应当感到愤怒。但他们却不知道如何处理这种“义怒”，于是任凭情绪控制自己、将愤怒施加给对方，也在不知不觉中将心里各种腐臭的污秽，就如骄傲、苦毒、嫉妒、狂妄、凶杀都一并倾泻了出去，还美其名曰“我是在义怒中伸张公义”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("3、两个层面")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("出现这些实践问题，都在于对“饶恕”缺乏正确的认识。因此当我们操练这一功课，尤其是在为此而祷告时，难以使自己的意念安置于真理之上，顺服于圣灵之中。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("之所以需要“饶恕”，是因为被得罪、被伤害。对方得罪、伤害了我，我们会感受到伤痛。这是因为对方的行为造成了我们的某种“利益”减损，从而带来心灵上的痛苦：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果有人凌辱了我、诅咒了我或打了我的脸（路加福音6:28~29a），这是对我尊严的伤害；如果有人抢了我的外衣（路加福音6:29b），这是对我财产的伤害；如果有人强逼着我走一里路（马太福音5:41），这是对我人身自由的伤害；当约伯落入苦难，他的朋友却指责他是恶有恶报，这伤害了他的情感（约伯记19:19）和对自身的道德认知（约伯记27:5~6）；又如一个为病重母亲祷告的孩子，若母亲最终离世，他或许一生都将对神怀怒，因为他感到是神夺走了亲人。例子还有许多。我们有形形色色、有名或无名的“利益”，一旦被伤害，就会感到疼痛。这疼痛会抓住我们的心，进而滋生出愤怒、愁苦、忧伤等等负面情绪。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("因此，一个自然而然的推论是：如果一个人没有了这些“利益”，也就不会被伤害。举个简单的例子：如果有人借了我的钱不还，你会愤怒、愁苦吗？我想多半不会。因为这个人并没有伤害你的财产，也没有伤害你对他的信任——他伤害的是我的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们也可以换种说法：当一个人从内心撇下了这些“利益”，伤害便不复存在，痛楚也随之消失。那么，随之而来的愤怒、愁苦、忧伤这些负面情绪，自然也就无从生起了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("想起了什么了吗？主耶稣说：“你们无论什么人，若不撇下一切所有的，就不能作我的门徒”（路加福音14:33）；“若有人要跟从我，就当舍己，天天背起他的十字架来跟从我。因为，凡要救自己生命的，必丧掉生命；凡为我丧掉生命的，必救了生命。”（路加福音9:24）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("撇下一切，甚至自己的生命，意味着我们不再从这些“神之外的利益”上寻求满足；而跟从耶稣，则意味着我们完全投靠在神的怀抱当中，只从神那里去获得满足。当私欲未被满足，痛苦就随之而生，进而滋生出各样的负面情绪：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("若我需要从尊严中获得满足，那么有人凌辱了我、诅咒了我或打了我的脸，我就会痛苦；若我需要从财产中获得满足，那么有人夺去我的外衣，我就会愤怒；若我需要从自由中获得满足，那么有人强逼我走一里路，我就会沮丧；若我需要从人的关怀、认可中获得满足，那么当我遭遇苦难，朋友却指责我是恶有恶报，我就会受伤；若我需要从亲人中获得满足，那么当有人将他们带走，我就会悲痛，甚至对那剥夺我满足的人切齿愤恨。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("私欲本身不是罪，但它会牵引诱惑人，最终导致人犯罪（雅各书1:14-15）。在我们当下的讨论中，这些罪具体表现为因被伤害而产生的苦毒、仇恨、忧愁，也就是“不饶恕”之罪。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以，当我们感到被人得罪时，我们必须正视并处理自己里面的私欲问题。人有形形色色的私欲，当它们被满足，可以带给人各种各样“利益”。平时你可能难以察觉，而一旦这些利益被侵犯了，感到疼痛了，在祷告中借着圣灵的光照，你就可以看到它们。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这时候，我们需要转向神，把自己投入他那深邃无垠的恩典之中，将自己沉浸在他那广阔无边的慈爱之内；为了神的缘故学习舍己、舍弃一切，摆脱私欲的缠累。向他呼喊：神啊，我只要你，我的好处不在你以外（诗篇16:2）！通过对神的仰望和依靠，我们可以超越、消解那份因私欲未被满足而产生的痛楚。当你真正超越了这份痛苦、让它在你心中失去力量时，你也就放下了对方对你的伤害。在这时，你便在个人的层面上，真正饶恕了对方。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但这只是“饶恕”的一个层面。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("饶恕还有另一个层面。无论对方是否直接伤害我们个人，当他干犯了神的律法，这就冒犯了神。他的行为必然会触动神的愤怒，而我们作为神的子民，既然与他的心意相连，此时心里感到愤怒也是自然的、必然的。这就叫“义怒”，出于公义的愤怒。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以，作为基督徒，如果我们面对罪恶却毫无这样的感受，那就需要去反思，你是否真的与主同心？我们要在祷告中祈求圣灵的帮助，让我们和神的情感共振。神对人类的罪愤怒（罗马书1:18）、对他子民的罪忧伤（以弗所书4:30）、焦急（哥林多后书11:29）。而如果神的子民却是“事不关己，高高挂起”，这当然是不正常的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么，当某个人犯罪冒犯了神，我们应该如何来对待这个触动神的愤怒、也激起你的义怒的人呢？主耶稣说，不要把你的怒火倾倒在他身上，而是要饶恕他、要给他怜悯、给他恩慈（路加福音6:37）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("区别于刚才个人层面的饶恕，这是公义层面的饶恕。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这种饶恕有三个特点，第一，它有部分是暂时的、属于今世的；第二，它另一部分则是彻底的、永恒的；第三，它始终带着对人的深切期盼。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣教导我们这样对待那些得罪神的人，是因为神自己就是这样做的。我们既然在“公义的愤怒”上与神同心，在“公义的饶恕”上，也当然应该与他同心。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("为什么说神这“公义的饶恕”有部分是暂时的、今世的呢？因为神从天上垂看世人，结果发现没有义人，连一个也没有。没有行善的，一个也没有（罗马书3:10~12）。神那公义的愤怒天天被人触动（罗马书1:18），此时此刻，他就正在怒火中烧！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("然而，他却没有立即来毁灭这个世界，他手中那装满愤怒的杯现在却没有倾倒出来，那些得罪他的人现在仍然在岁月静好。他们现在仍然又吃又喝，又娶又嫁，又买又卖，又耕种又盖造（路加福音17：27~28）。这是因为神现在仍暂时饶恕着这些人，才使他们的性命可以暂时存活。但是，终有一天，在今世过去之后，他那积累的烈怒将会倾泻而出。到那个时候，这些人会向山和岩石说：倒在我们身上吧，把我们藏起来，让我们可以躲避神的愤怒！（启示录6:16）这些人会祈求神说：我情愿挖掉双眼，砍断双腿，也不愿意和你同在，因为你把怒气像汪洋一样倾泻在我身上！（马太福音18:8~9）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们这公义层面的饶恕，有部分也是这样的。面对冒犯他的人，神没有现在就把愤怒倾倒出来，神的子民也不要。神在今世暂时饶恕着他们，神的子民也要这样饶恕；神在永恒中必会报复、惩罚，使他的公义得伸张，神的子民则要等待、盼望、甚至祈求这一天的到来。所以保罗劝我们：“不要自己伸冤，宁可让步，听凭主怒，因为经上记着，主说‘伸冤在我，我必报应。’”（罗马书12:19）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("为什么说神这“公义的饶恕”有部分又是彻底的、永恒的呢？因为从那没有善行的众人中，神凭他的恩典拣选了一部分人成为他的子民，赐给他们圣灵，重生他们，引导他们认罪悔改。神已经把对他们的愤怒倾倒在了他们所依靠的那位救主——拿撒勒人耶稣身上。他为他们的罪死了，三天后复活，还清了他们在神那里的所有罪债。所以对他们的过犯，神已经彻底饶恕、永远不再惩罚了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们这公义层面的饶恕，有部分也是这样的。面对那些有过犯的神的子民，当他们认罪、悔改，神已经彻底赦免了、饶恕了，其他的人有什么资格不去赦免、饶恕，而要追讨到底呢？所以保罗劝我们，若有弟兄犯了罪而忧愁，众人挽回他、甚至责罚他，也就够了，更要赦免他、安慰他，免得他忧愁太过，甚至沉沦了。（哥林多后书2:6~7）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("为什么说神这“公义的饶恕”又是带着对人的深切期盼呢？因为人得罪了神，神却没有立即施行毁灭，而是给他时间、机会，为叫他能认罪、悔改、信靠他所赐下的救恩。这不是他耽延，乃是他宽容，不愿有一人沉沦，乃愿人人都悔改（彼得后书3:9）。正像他曾经告诉他的仆人以西结：“我断不喜悦恶人死亡，唯喜悦恶人转离所行的道而活”。（以西结书33:11）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们这公义层面的饶恕，也是带着对人回转的深切盼望。这饶恕不是“放下”，而是“放不下”，放不下他的灵魂，不忍看到他沉沦，盼望他认识真道。所以保罗才劝我们：要用温柔劝诫那抵挡的人，或者神给他们悔改的心，可以明白真道，叫他们这已经被魔鬼任意掳去的，可以醒悟，脱离他的网罗（提摩太后书2:26）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("以上，这就是圣经中讲的饶恕。有个人层面的，也有公义层面的。当某个人犯罪直接得罪了我们，我们既需要对他施以个人层面的饶恕，也要对他施以公义层面的饶恕。而即使他没有得罪我们个人，如果我们与神同心，他得罪神的行为也理当引起我们的义怒，但我们也仍应向他施以公义层面的饶恕。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("4、三个方法")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在解释了这么多之后，那我们应当如何实际地去操练饶恕呢？我将其总结为以下几点：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第一，仰望上帝，舍弃自己。仰望神，并将自己全然沉浸于神那无限的恩典与慈爱之中；靠着圣灵的帮助，舍弃自我，摆脱私欲的缠累。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第二，控制怒气，交托于主。无论是出于私欲受挫的愤怒，还是出于公义未彰的义怒，都不要任由怒火驱使你的言行。把你的一切怒气交托给公义的主，相信他必有伸张公义的时候。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第三，怀着盼望，用心行动。带着盼望他与神和好的心，采取行动。你可以是为他祷告，可以是温柔劝诫，甚至可以是施以管教。但怎么行动不是重点，你的心才是。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我知道这很难，尤其是当我们个人被伤害的时候。但操练饶恕，像一切的敬虔操练一样，都需要反复经历”跪下来祷告，爬起来行动”的过程。在这个过程中，不要丧失信心，因为靠着那加给我们力量的圣灵，我们凡事都能作（腓立比书4:13）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("5、两个例子")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("请允许我举两个真实的例子：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我儿子小时候，有一次对我出言不逊，瞬间点燃了我的怒火。但圣灵立刻提醒我，这怒火源于他伤害了我的“利益”——一个父亲在儿子面前的尊严。我需要从这尊严上获得满足，而他的行为导致了这私欲受挫，从而造成我的痛苦，激起我的怒气。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("于是我向神祈求，帮助我撇弃这所谓的尊严；帮助我谦卑下来，承认自己的“贫穷”（路加福音6:20）：我并没有一个”儿子”，只有一个神托付在我身边、需要我去服侍的男孩；我也并没有什么“父亲在儿子面前的尊严”，因为一切对赞赏与善待的渴望，都应当唯独从神那里得着满足——而他早已借着十字架，将那份长阔高深的爱完全赐给了我！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当圣灵在祷告中帮助我脱离这私欲的捆绑，他对我的伤害也随之消散。于是，在个人层面，我便真正饶恕了他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但他的行为也确实得罪了神（以弗所书6:2）。我若与神同心，就不能视而不见，而理应为他的罪感到愤怒、忧伤。因此，我仍需要向他施以公义层面的饶恕：带着盼望他与神和好的心，为他祷告，指出他得罪神之处，劝勉他认罪悔改，甚至视情况需要，为了阻止他恶行的滋长，施以适当的体罚（箴言22:15）。这样，在公义层面，我也才饶恕了他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第二个例子发生在教会一位姐妹身上。她将自己一套配有全新家具的房子出租出去。租约到期、房款结清后，她才发现租客竟把她新配的床垫偷偷换成了旧的，而自己在交接收房时因一时疏忽未能察觉。这位姐妹心中气恼难平，却不知该如何应对。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当她告诉我这件事，我问她：“您之所以气恼，是因为您的新床垫没有了，是吗？”她点了点头。我接着问：“但我们不妨想一想——您真的确定那个新床垫是属于您吗？主耶稣说：‘贫穷的人有福了，因为神的国是你们的’；又说：‘富足的人有祸了，因为你们受过你们的安慰’（路加福音6:20, 24）。当我们以为自己‘拥有’什么的时候，就不再是贫穷人，也不再需要完全依赖主耶稣。此时，我们已成了富足的人，自然就会从这些所谓‘属于自己的东西’上寻求安慰。但如果我们是这样，那就有祸了！现在，这位租客夺走了您所依凭的安慰，所以您感到恼怒。但您真的确定自己‘拥有’这个新床垫，并因此有权从中得安慰吗？”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("圣灵此时光照了这位姐妹，让她看见自己其实一无所有，一切所有的都属于神。正如经上所记：“赏赐的是耶和华，收取的也是耶和华。耶和华的名是应当称颂的！”（约伯记1:21）那一刻，她对那位租客的恼恨便悄然消散。在个人层面，她已真正饶恕了他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当她向我分享了圣灵在她心中的这些引导后，我又鼓励她：“但这位租客的行为确实是错的，是得罪神的。这一点我们无需掩饰，对这种行为产生公义的愤怒，也是合宜的。只是，这份愤怒究竟是源于私欲未得满足，还是因为公义受到了践踏，我们往往确实难以分辨。但无论如何，我们不应把愤怒发泄出来，而要全然交托给主。对于这位租客，我们依然要爱他，并用行动去爱。您可以为他的悔改归正祷告；甚至，如果您的精力、时间和条件允许，为了制止他继续在恶行中沉沦，您也可以选择报警或向法院提起诉讼。然而，做这些，不是为了挽回您自己的损失——因为您其实本来就一无所有；也不是为了伸张公义——因为公义唯有在主那里才能真正伸张；而纯粹是为了这租客的益处，盼望他能回转。” ")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("后来，圣灵继续在她心里动工，经过祷告中的综合考虑，她最终没有启动法律程序，而是选择在祷告中将这位租客交托给主。如此，在公义的层面上，她也完成了对他的饶恕。")])],1)])}),[],!1,null,null,null);s.default=e.exports}}]);